/bin/bash -lc "python - <<'PY'
import csv,re,json,collections
bor=list(csv.DictReader(open('borzoi_targets_human.tsv'),delimiter='\\t'))
B=set(re.findall(r'ENCSR[A-Z0-9]+','\\n'.join(r['file'] for r in bor)))
E={}
for r in csv.reader(open('encode_report.tsv',errors='ignore'),delimiter='\\t'):
 if r and r[0]"'!='"'Accession': E[r[0]]=r[1] if len(r)>1 else ''
S={a['external_id'] for a in json.load(open('cistrome_all.json'))['samples'] if a['id']<=100000} # we'll later exact Sei
sei_ids=[]
samples={a['id']:a for a in json.load(open('cistrome_all.json'))['samples']}
for s in open('sei-framework/model/target.names'):
 if m:=re.search(r'ID:(\\d+)\\s*"'$'"',s): sei_ids.append(samples[int(m.group(1))]['external_id'])
S=set(sei_ids)
G={x for x in S if x.startswith('GSM')}
ind=[]
for e in B&E.keys():
 gsm=set(re.findall(r'GSM\\d+',E[e]))
 if gsm&G: ind.append((e,gsm&G))
print('B report coverage',len(B&E.keys()),'crosswalk experiments with Sei GSM',len(ind),'unique matching GSM',len(set().union(*(x[1] for x in ind)) if ind else set()))
print(ind[:30])
PY"

